3	import { CONFIG } from '../../config';
4	
5	/* =====================================================================
6	   HÌNH HỌC NGƯỜI ĐI BỘ — một hình gộp cho mọi kiểu người (spec G5, G8): thân, đầu, tóc, hai tay (bắp tay áo cộc + cẳng tay),
7	   hai chân (đùi + ống quần + giày), nón lá, ba lô. Theo personGeo của bản dựng thử, bớt cạnh để ≤ CONFIG.people.maxVerts đỉnh.
8	   Mét, tỉ lệ 1: cao ≈ 1,65 m (≈ 1,79 m tính chóp nón), mặt hướng +X, rộng theo Z, chân chạm y = 0. Có index, không uv.
9	   Thuộc tính đỉnh (shader ở material.ts đọc):
10	   - aPart: 0 thân/đầu/tóc, 1 chân trái (−Z, vì mặt hướng +X), 2 chân phải (+Z), 3 tay trái, 4 tay phải, 5 nón lá, 6 ba lô (5, 6 bật theo cờ instance)
11	   - aSeg: 0 đoạn trên, 1 đoạn dưới khớp (quay thêm quanh aPivot2); aPivot: cao độ hông / vai; aPivot2: cao độ gối / khuỷu
12	   - aMask: 0 màu cố định aFix, 1 áo (instanceColor), 2 quần (aPants); aFix: màu cố định tuyến tính (da, tóc, giày, nón, ba lô)
13	   ===================================================================== */
14	export const PP_HIP = 0.86, PP_KNEE = 0.46, PP_SHOULDER = 1.37, PP_ELBOW = 1.1;   // m — cao độ khớp ở tỉ lệ 1
15	export enum PpPart { Body = 0, LegL = 1, LegR = 2, ArmL = 3, ArmR = 4, Hat = 5, Pack = 6 }
