1	import * as THREE from 'three';
2	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
3	import { CONFIG } from '../../config';
4	import { scene } from '../../core/renderer';
5	import { MAT } from '../../core/materials';
6	import { bentBox, bentPlane, shadowed } from '../../common/geometry';
7	import { ROADS3 } from '../../environment/streets';
8	import { deckY } from './profile';
9	
10	/* ============================ Cầu Rồng: mặt cầu ============================ */
11	export function buildBridgeDeck() {
12	  const L = CONFIG.length, hw = CONFIG.width / 2, segs = 260;
13	  const med = CONFIG.median / 2;
14	  const carriage = CONFIG.lanesPerDir * CONFIG.laneWidth + CONFIG.shoulder; // 13,25 m mỗi chiều
15	  const sideIn = med + carriage;                                             // mép trong lề đi bộ
16	  const conc = [], steel = [], paver = [], rail = [], led = [];
17	  conc.push(bentBox(L, 0.5, CONFIG.width, 0, -0.25, 0, segs, deckY));             // bản mặt cầu
18	  steel.push(bentBox(570, 3.0, 26, 0, -2.0, 0, 220, deckY));                       // dầm hộp thép ẩn dưới
19	  conc.push(bentBox(L, 0.3, CONFIG.median, 0, 0.15, 0, segs, deckY));              // dải phân cách giữa 6 m
20	  for (const s of [-1, 1]) {
21	    paver.push(bentBox(L, 0.25, CONFIG.sidewalk, 0, 0.125, s * (sideIn + CONFIG.sidewalk / 2), segs, deckY)); // lề đi bộ 2,5 m
22	    conc.push(bentBox(L, 0.9, 0.35, 0, 0.45, s * (sideIn - 0.175), segs, deckY));   // gờ chắn xe
23	    rail.push(bentBox(L, 0.08, 0.14, 0, 1.12, s * (hw - 0.1), segs, deckY));        // tay vịn
24	    rail.push(bentBox(L, 0.06, 0.06, 0, 0.6, s * (hw - 0.1), segs, deckY));
25	    led.push(bentBox(L, 0.05, 0.1, 0, 1.19, s * (hw - 0.1), segs, deckY));          // dải LED trên lan can
26	    conc.push(bentBox(L, 0.35, 0.3, 0, -0.1, s * (hw + 0.1), segs, deckY));         // gờ mép ngoài
27	  }
28	  scene.add(shadowed(new THREE.Mesh(mergeGeometries(conc), MAT.concrete)));
29	  scene.add(shadowed(new THREE.Mesh(mergeGeometries(steel), MAT.girder)));
30	  scene.add(shadowed(new THREE.Mesh(mergeGeometries(paver), MAT.paver), false, true));
31	  scene.add(shadowed(new THREE.Mesh(mergeGeometries(rail), MAT.rail), true, false));
32	  scene.add(new THREE.Mesh(mergeGeometries(led), MAT.ledRail));
33	
34	  // Mặt đường 6 làn (2 chiều × 3 làn) — gom chung với đường bờ để giảm draw call
35	  ROADS3.push(bentPlane(L, carriage, 0, 0.02, med + carriage / 2, segs, deckY));
36	  ROADS3.push(bentPlane(L, carriage, 0, 0.02, -(med + carriage / 2), segs, deckY, true));
37	
38	  // Cột lan can (InstancedMesh)
39	  const n = Math.floor(L / 2.2), post = new THREE.InstancedMesh(new THREE.BoxGeometry(0.1, 1.15, 0.1), MAT.rail, n * 2);
40	  const m = new THREE.Matrix4();
41	  let k = 0;
42	  for (let i = 0; i < n; i++) for (const s of [-1, 1]) {
43	    const x = -L / 2 + (i + 0.5) * 2.2;
44	    m.makeTranslation(x, deckY(x) + 0.575, s * (hw - 0.1)); post.setMatrixAt(k++, m);
45	  }
46	  post.castShadow = true; scene.add(post);
