1	// Kiểm tra người đi bộ thực tế hơn (docs/superpowers/specs/2026-11-11-cay-va-nguoi-thuc-te-design.md, Task 5 của plan).
2	//  1. systems: đúng 3 hệ ttl-people 80, sh-people 76, dragon-people 70; mỗi hệ đúng 1 InstancedMesh, cùng một vật liệu peopleWalk;
3	//     có instanceColor (màu áo) đủ số người, aVar / aPants là thuộc tính instance.
4	//  2. noOldShape: không còn lưới người nào ≤ 200 đỉnh (ống trụ + cầu cũ).
5	//  3. moving: sau 60 khung, ≥ 60 % instance đã đổi vị trí; số instance đứng yên khớp số người 'stand' (±1);
6	//     mọi người thẳng đứng, người đang đi quay mặt (+X của hình) theo chiều đi.
7	//  4. insideSidewalk: mọi instance hiện nằm trong dải lề của cầu mình, chân đúng mặt lề (không lơ lửng, không chìm).
8	//  5. stormClear: bão ⇒ giữa chừng 0 < hiện < tổng, hết thời gian dọn 0 ở cả 3 hệ; hết bão ⇒ hiện đủ.
9	//  6. toggleBack: bấm #btnTtlPeople hai lần (click()) ⇒ nhóm ẩn rồi hiện lại đủ 80.
10	//  7. dragonLod: camera xa tim Cầu Rồng 2 000 m ⇒ nhóm dragon-people ẩn; về 300 m ⇒ hiện.
11	//  8. randKept: speed 7 tàu chạy chung trùng main (người Cầu Rồng không chạm rand()).
12	//  9. Không lỗi console (kể cả lỗi biên dịch shader).
13	// 10. Ảnh (bỏ bằng --no-shots) tests/screens/people-*.png: lề Cầu Rồng gần ~10 m (ngày), người đứng gần đầu rồng, người chạy,
14	//     lề Trần Thị Lý, lề Cầu sông Hàn, Bạch Đằng, và lề Cầu Rồng ban đêm.
15	//
16	//   npm run build && npm run test:people [-- --no-shots]
17	import { fileURLToPath } from 'node:url';
18	import { mkdirSync } from 'node:fs';
19	import { serveDir, launch, openApp, frames } from './lib.mjs';
20	import { setWx } from './weather-lib.mjs';
21	
22	const NO_SHOTS = process.argv.includes('--no-shots');
23	const SCREENS = fileURLToPath(new URL('./screens/', import.meta.url));
24	mkdirSync(SCREENS, { recursive: true });
25	const problems = [];
26	const check = (ok, msg) => { console.log(`${ok ? 'ĐẠT ' : 'LỖI '} ${msg}`); if (!ok) problems.push(msg); return ok; };
27	
28	// Mốc đo trên main 43cec90 (chép từ tests/traffic-check.mjs): speed của 7 tàu chạy chung
29	const MAIN_BOAT_SPEEDS = [4.834048458375037, 3.4622229826636612, 3.367667659651488, 4.561683705076575, 4.302534147165716, 3.222870459780097, 4.6476020980626345];
30	const COUNTS = { 'ttl-people': 80, 'sh-people': 76, 'dragon-people': 70 };
31	const NAMES = Object.keys(COUNTS);
32	/* Dải lề theo tọa độ cục bộ của cầu (chép từ src/config.ts):
33	   Cầu Rồng: width 37,5, sidewalk 2,5 ⇒ |z| ∈ [16,25; 18,75]. Trần Thị Lý: deckWidth 34,5 ⇒ hw 17,25, sidewalk 3,25 ⇒ |z| ∈ [14; 17,25];
34	   cầu Nguyễn Văn Trỗi: nvtZ −65, nvtWidth 9 ⇒ z ∈ [−69,5; −60,5]. Cầu sông Hàn: deckWidth 12,9 ⇒ hw 6,45, sidewalk 2 ⇒ |z| ∈ [4,45; 6,45];
35	   Bạch Đằng (trục z): x ∈ [−286; −262] (mép kè x = −262). */
36	const inBand = (name, p) => {
37	  const az = Math.abs(p.z);
38	  if (name === 'dragon-people') return az >= 16.25 && az <= 18.75;
39	  if (name === 'ttl-people') return p.i < 46 ? az >= 14 && az <= 17.25 : p.z >= -69.5 && p.z <= -60.5;
40	  return p.i < 36 ? az >= 4.45 && az <= 6.45 : p.x >= -286 && p.x <= -262;
41	};
42	
43	const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
44	const browser = await launch();
45	const { page, errors } = await openApp(browser, srv.url, { width: 960, height: 540 });
46	
47	const setNight = async (v) => {
48	  await page.evaluate((v) => { window.__app.dayNight.target = v; window.__app.dayNight.night = v; }, v);
49	  await page.waitForFunction((v) => Math.abs(window.__app.dayNight.night - v) < 1e-6, v, { timeout: 60000 });
50	  await frames(page, 3);
51	};
52	const hideUi = (on) => page.evaluate((on) => document.querySelectorAll('body *').forEach((e) => { if (!e.matches('canvas') && !e.querySelector('canvas')) e.style.visibility = on ? 'hidden' : ''; }), on);
53	const setCam = (pos, tgt) => page.evaluate(([p, t]) => { const { camera, controls } = window.__app; camera.position.set(p[0], p[1], p[2]); controls.target.set(t[0], t[1], t[2]); controls.update(); }, [pos, tgt]);
54	const systems = () => page.evaluate(() => window.__app.people?.systems() ?? []);
55	const positions = (name) => page.evaluate((n) => window.__app.people?.positions(n) ?? [], name);
56	// Chỗ camera thấy cả 3 cầu trong tầm cập nhật người: cách tâm Trần Thị Lý ≈ 1 310 m (< 1 500), Cầu sông Hàn ≈ 1 100 m (< 1 200), Cầu Rồng 200 m
57	const ALL_CAM = [[0, 200, 0], [0, 0, 100]];
58	
59	try {
60	  await setNight(0);
61	  await setCam(...ALL_CAM); await frames(page, 3);
62	
63	  /* ---------- 1. systems ---------- */
64	  const sy = await systems();
65	  check(sy.map((s) => s.name).join(',') === NAMES.join(','), `systems: đủ 3 hệ người (${sy.map((s) => s.name).join(',') || 'không có __app.people'})`);
66	  for (const n of NAMES) {
67	    const s = sy.find((x) => x.name === n);
68	    check(!!s && s.count === COUNTS[n] && s.meshes === 1, `systems: ${n} ${s?.count} người (mốc ${COUNTS[n]}), ${s?.meshes} InstancedMesh`);
69	    check(!!s && s.colors === COUNTS[n] && s.shirtKinds >= 4 && s.instAttrs, `systems: ${n} có instanceColor đủ ${s?.colors} người, ${s?.shirtKinds} màu áo, aVar/aPants là thuộc tính instance (${s?.instAttrs})`);
70	  }
71	  check(sy.length === 3 && new Set(sy.map((s) => s.material)).size === 1 && sy[0]?.materialName === 'peopleWalk', `systems: 3 hệ cùng một vật liệu peopleWalk (${sy.map((s) => s.materialName).join(',')})`);
72	
73	  /* ---------- 2. noOldShape ---------- */
74	  const old = await page.evaluate(() => { const out = []; window.__app.scene.traverse((o) => { if (o.isMesh && /-people$/.test(o.parent?.name ?? '') && o.geometry.attributes.position.count <= 200) out.push(`${o.parent.name}:${o.geometry.attributes.position.count}`); }); return out; });
75	  check(old.length === 0, `noOldShape: không còn lưới người ≤ 200 đỉnh (${old.join(', ')})`);
76	  check(sy.length === 3 && sy.every((s) => s.verts > 200 && s.verts <= 900), `noOldShape: hình người ${sy.map((s) => s.verts).join('/')} đỉnh (≤ 900)`);
77	
78	  /* ---------- 3. moving ---------- */
79	  const p0 = {}; for (const n of NAMES) p0[n] = await positions(n);
80	  await frames(page, 60);
81	  for (const n of NAMES) {
82	    const a = p0[n], b = await positions(n);
83	    if (!a.length || a.length !== b.length) { check(false, `moving: ${n} không đọc được vị trí`); continue; }
84	    let moved = 0, still = 0, badHead = 0, tilted = 0;
85	    const stands = b.filter((p) => p.kind === 'stand').length;
86	    b.forEach((p, i) => {
87	      const dx = p.x - a[i].x, dz = p.z - a[i].z, d = Math.hypot(dx, dz);
88	      if (d > 0.01) moved++; else still++;
89	      if (p.upY < 0.999) tilted++;
90	      if (d > 0.01 && d < 10 && (p.fwd[0] * dx + p.fwd[2] * dz) / d < 0.95) badHead++;   // bỏ qua người vừa quay vòng về đầu dải
91	    });
92	    check(moved >= 0.6 * b.length, `moving: ${n} ${moved}/${b.length} người đã đổi vị trí sau 60 khung`);
93	    check(Math.abs(still - stands) <= 1, `moving: ${n} ${still} người đứng yên, ${stands} người kiểu 'stand'`);
94	    check(tilted === 0 && badHead === 0, `moving: ${n} mọi người thẳng đứng (${tilted} nghiêng), quay mặt theo chiều đi (${badHead} sai hướng)`);
