100	    const out = ps.filter((p) => !inBand(n, p)), off = ps.filter((p) => p.y < p.ground - 1e-4 || p.y > p.ground + 1e-3);
101	    check(ps.length === COUNTS[n] && out.length === 0, `insideSidewalk: ${n} ${ps.length} người, ${out.length} ngoài dải lề (${out.slice(0, 3).map((p) => `#${p.i} x ${p.x.toFixed(1)} z ${p.z.toFixed(2)}`).join('; ')})`);
102	    check(off.length === 0, `insideSidewalk: ${n} chân đúng mặt lề (${off.length} lệch: ${off.slice(0, 3).map((p) => `#${p.i} y ${p.y.toFixed(3)} / ${p.ground.toFixed(3)}`).join('; ')})`);
