113	  check(mid.length === 3 && mid.every((s) => s.visible > 0 && s.visible < s.count), `stormClear: giữa chừng (clear ${midK.toFixed(2)}) ${mid.map((s) => `${s.name} ${s.visible}/${s.count}`).join(', ')}`);
114	  await page.waitForFunction(() => window.__app.weather.fx().clear >= 1, null, { timeout: 600000 }); await frames(page, 2);
