133	  const dragonVis = async (pos) => { await setCam(pos, [0, 8, 0]); await frames(page, 3); return page.evaluate(() => ({ v: window.__app.scene.getObjectByName('dragon-people')?.visible, d: window.__app.camera.position.length() })); };
134	  const far = await dragonVis([0, 300, 1980]), near = await dragonVis([0, 120, 270]);
135	  check(far.v === false && near.v === true, `dragonLod: camera cách ${far.d.toFixed(0)} m ⇒ ẩn (${far.v}); ${near.d.toFixed(0)} m ⇒ hiện (${near.v})`);
