138	  if (!NO_SHOTS) {
139	    await hideUi(true);
140	    const shot = async (name) => { await frames(page, 3); await page.screenshot({ path: `${SCREENS}people-${name}.png` }); };
141	    /* Đặt camera theo người i của hệ (tọa độ thế giới): off = lệch camera (m), lookY = nhìn cao hơn chân */
